/usr/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
p=None; n=0; spans={}
for s in Path('prior/repair.diff').read_text().splitlines():
 if s.startswith('+++ b/'):
  p=s[6:]; p='candidate/statement-ledger.md' if p=='docs/statement-ledger.md' else 'lean/'+p
 elif s.startswith('@@'):
  n=int(re.search(r'\\+(\\d+)',s).group(1))
 elif s.startswith('+'):
  spans.setdefault(p,[]).append((max(1,n-4),n+5)); n+=1
 elif s.startswith(' '): n+=1
for p,rr in spans.items():
 if p in ('candidate/statement-ledger.md','lean/provenance/manuscript-anchor.json'): continue
 print('\\nFILE',p)
 if not Path(p).exists(): print('MISSING'); continue
 ls=Path(p).read_text().splitlines(); merged=[]
 for a,b in rr:
  if merged and a<=merged[-1][1]+1: merged[-1][1]=max(merged[-1][1],b)
  else: merged.append([a,b])
 for a,b in merged:
  for i in range(a,min(b,len(ls))+1): print(f'{i}: {ls[i-1]}')
PY"

